describe('403 Error Handling - Access Denied Page', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display access denied page when API returns 403 status', () => {
    // Intercept the API call with a 403 response
    cy.intercept('GET', '/api/user/data', {
      statusCode: 403,
      body: { error: 'Forbidden', message: 'You do not have permission to view this resource.' }
    }).as('getUserData403');

    // Attempt to access restricted data
    cy.get('[data-testid="user-data-button"]').click();

    // Wait for the 403 response
    cy.wait('@getUserData403');

    // Verify access denied page is displayed
    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Forbidden');
    cy.get('[data-testid="error-message"]').should('contain', 'You do not have permission to view this resource.');

    // Verify navigation to error page is not possible
    cy.get('[data-testid="user-data-button"]').should('be.disabled');
    cy.get('[data-testid="logout-button"]').should('be.disabled');

    // Verify user is not logged out
    cy.get('[data-testid="user-name"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');

    // Verify error page has correct styling
    cy.get('[data-testid="error-container"]').should('have.class', 'error-page');
  });

  it('should handle 403 error with custom error page and retry button', () => {
    // Intercept the API call with a 403 response
    cy.intercept('GET', '/api/user/data', {
      statusCode: 403,
      body: { error: 'Forbidden', message: 'Access denied due to insufficient permissions.' }
    }).as('getUserData403');

    // Attempt to access restricted data
    cy.get('[data-testid="user-data-button"]').click();

    // Wait for the 403 response
    cy.wait('@getUserData403');

    // Verify access denied page is displayed
    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Forbidden');

    // Verify retry button is present and functional
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();

    // Verify retry button triggers API call
    cy.intercept('GET', '/api/user/data', {
      statusCode: 200,
      body: { data: 'User data loaded successfully' }
    }).as('getUserDataRetry');

    cy.wait('@getUserDataRetry');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-name"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');

    // Verify error page is no longer visible
    cy.get('[data-testid="access-denied-page"]').should('not.exist');
  });
});
